#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
using namespace std;

class GCounter {
    vector<int> counts;
public:
    GCounter(int nodes) : counts(nodes, 0) {}
    void increment(int node) { counts[node]++; }
    int value() const { return accumulate(counts.begin(), counts.end(), 0); }
    void merge(const GCounter& other) {
        for (size_t i = 0; i < counts.size(); i++)
            counts[i] = max(counts[i], other.counts[i]);
    }
};

int main() {
    GCounter a(3), b(3);
    a.increment(0); a.increment(0);
    b.increment(1); b.increment(1); b.increment(1);
    cout << "A: " << a.value() << ", B: " << b.value() << endl;
    a.merge(b);
    cout << "Merged: " << a.value() << endl;
    return 0;
}
